const D:usize=8;const L:usize=132;
unsafe fn put64(o:*mut u8,p:usize,x:i64){let b=x as u64;for j in 0..8{*o.add(p+j)=(b>>(8*j)) as u8;}}
fn same(a:&[i64;64],ar:usize,b:&[i64;64],br:usize,w:usize)->bool{for j in 0..w{if a[ar*w+j]!=b[br*w+j]{return false}}true}
#[no_mangle]pub unsafe extern "C" fn two_dimensional_string_matching(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<6||length>L{return -1}let rr=*input;let cc=*input.add(1);let hr=*input.add(2);let wc=*input.add(3);if rr<1||rr>8||cc<1||cc>8||hr<1||hr>rr||wc<1||wc>cc{return -1}let r=rr as usize;let c=cc as usize;let h=hr as usize;let w=wc as usize;if length!=4+r*c+h*w{return -1}let mut text=[0i64;64];let mut pat=[0i64;64];let mut p=4;for i in 0..r*c{text[i]=*input.add(p);p+=1;if text[i]<0||text[i]>3{return -1}}for i in 0..h*w{pat[i]=*input.add(p);p+=1;if pat[i]<0||pat[i]>3{return -1}}let mut prefix=[0i64;D];for i in 1..h{let mut q=prefix[i-1] as usize;while q>0&&!same(&pat,i,&pat,q,w){q=prefix[q-1] as usize}if same(&pat,i,&pat,q,w){q+=1}prefix[i]=q as i64}let mut mark=[false;D*D*D];for tr in 0..r{for col in 0..=c-w{for pr in 0..h{let mut eq=true;for j in 0..w{if text[tr*c+col+j]!=pat[pr*w+j]{eq=false}}mark[(tr*D+col)*D+pr]=eq}}}let mut mr=[0i64;D*D];let mut mc=[0i64;D*D];let mut count=0;for col in 0..=c-w{let mut q=0;for tr in 0..r{while q>0&&!mark[(tr*D+col)*D+q]{q=prefix[q-1] as usize}if mark[(tr*D+col)*D+q]{q+=1}if q==h{mr[count]=(tr+1-h) as i64;mc[count]=col as i64;count+=1;q=prefix[h-1] as usize}}}let bytes=8*(1+2*count);if output.is_null()||capacity<bytes{return -2}put64(output,0,count as i64);for i in 0..count{put64(output,8*(1+2*i),mr[i]);put64(output,8*(2+2*i),mc[i]);}bytes as i64}
